  w: V7World,
  s: V7Stack,
  unitMass: number,
  layer: BranchLayer,
) {
  const base = w.resources.find((r) => r.id === s.resource);
  if (!base || !base.properties)
    throw new Error('Missing material property schema.');
  s.physical = {
    unitMass,
    unitWater: unitMass * layer.waterFraction,
    unitSolids: unitMass * (1 - layer.waterFraction),
  };
