      'material-combine-status',
      'Observed actual supplies and any named personal operation; no material or reward changes.',
      {
        sources: v7Json(
          selected.map((s) => ({
            id: s.id,
            quantityTenths: Math.round(s.quantity * 10),
            version: version(s),
