export function rootDecayRate(w: V7World, s: V7Stack) {
  const p = rootProcessing(w, s);
  return p
    ? p.drying && p.fraction >= 1 && p.dry
      ? 0.35
      : 1 + 0.25 * p.fraction
    : 1;
}

