    safe:
      ['root', 'crushed-root'].includes(s.resource) &&
      !s.componentLots &&
      r?.nutrition === 14 &&
      r.toxicity === 0 &&
      (s.decay ?? 0) < (r.properties?.decay ?? 0),
    volume:
      typeof volume === 'number'
