    'stone-contact',
    stones.every((s) => smallStone(c.world, s)),
    stones.map((s) => ({
      id: s.id,
      quantity: s.quantity,
      hardness: collectiveFoodProfile(c.world, s)?.properties?.hardness ?? null,
