export const SMALL_DRYING = 'root-small-drying';
export function smallSpatial(x: number, y: number, g: V7Data): V7Spatial {
  return {
    x,
    y,
    angle: 0,
    shape: {
      kind: 'rectangle',
      width: Number(g.width),
      height: Number(g.height),
    },
    solid: false,
    reserved: true,
    interaction: 0.65,
    entrances: [],
