    height = spatial.shape.kind === 'rectangle' ? spatial.shape.height : 0;
  const points = [-0.5, 0, 0.5].flatMap((x) =>
    [-0.5, 0, 0.5].map((y) =>
      openConditions(w, {
        x: spatial.x + x * width,
        y: spatial.y + y * height,
      }),
    ),
  );
