    parts = c.world.stacks.filter(
      (s) => j.escrow.includes(s.id) && s.reservedFor === j.id,
    );
  if (!o || parts.length !== j.escrow.length) {
    smallStop(
      c.world,
      c.actor,
      j,
      'Actual input or support was lost; surviving material released once.',
    );
    return workResult(j);
  }
  let valid =
    j.mode === 'build'
      ? parts.some(
          (s) =>
