    const old = before.actors.find((a) => a.id === actor.id);
    const events = world.events.filter(
      (e) => e.actor === actor.id || e.target === actor.id,
    );
    if (
      world.config.collective.arm === 'B' &&
      old &&
      actor.vitals.health < old.vitals.health
