  if ((stack.mantle || stack.frictionKit || stack.waterCup) && n !== 1)
    throw new Error('Equipment is one indivisible persistent item.');
  const recipient = give
    ? world.actors.find(
        (a) =>
          a.id === action.args.recipient &&
          a.id !== actor.id &&
          a.vitals.health > 0,
