  world.terrain.forEach((row, y) => {
    Array.from(row).forEach((cell, x) => {
      if (cell === '~' && (!known || known.has(`${String(x)},${String(y)}`)))
        result.push({
          x: x + 0.5,
          y: y + 0.5,
          angle: 0,
          shape: { kind: 'rectangle', width: 1, height: 1 },
          solid: true,
          interaction: 0,
