  if (object.entrances.length)
    return object.entrances.some(
      (p) =>
        v7Distance(actor.position, {
          x:
            object.x +
            p.x * Math.cos(object.angle) -
            p.y * Math.sin(object.angle),
          y:
            object.y +
            p.x * Math.sin(object.angle) +
            p.y * Math.cos(object.angle),
