    [0, -h / 2 + t / 2, w, t],
    [-w / 2 + t / 2, 0, t, h],
    [w / 2 - t / 2, 0, t, h],
    [-(w + d) / 4, h / 2 - t / 2, (w - d) / 2, t],
    [(w + d) / 4, h / 2 - t / 2, (w - d) / 2, t],
  ].map(([x = 0, y = 0, width = 1, height = 1]) => ({
    x: spatial.x + x * Math.cos(spatial.angle) - y * Math.sin(spatial.angle),
    y: spatial.y + x * Math.sin(spatial.angle) + y * Math.cos(spatial.angle),
