function routeQueue(work: V7Work) {
  type Entry = { id: number; score: number; order: number };
  const heap: Entry[] = [];
  const less = (a: Entry, b: Entry): boolean => {
    work.spend();
    return a.score < b.score || (a.score === b.score && a.order < b.order);
  };
  return {
    push(entry: Entry) {
      let index = heap.length;
      heap.push(entry);
      while (index > 0) {
        const parent = Math.floor((index - 1) / 2),
          value = heap[parent];
        if (!value || !less(entry, value)) break;
        heap[index] = value;
        index = parent;
      }
      heap[index] = entry;
    },
    pop(): Entry | undefined {
      const first = heap[0],
        last = heap.pop();
      if (heap.length && last) {
        let index = 0;
        for (;;) {
          let child = index * 2 + 1;
          const left = heap[child],
            right = heap[child + 1];
          if (!left) break;
          if (right && less(right, left)) child++;
          const next = heap[child];
          if (!next || !less(next, last)) break;
          heap[index] = next;
          index = child;
        }
        heap[index] = last;
      }
      return first;
    },
  };
