    width = Math.round(world.config.width / spacing),
    height = Math.round(world.config.height / spacing);
  const position = (id: number): V7Point => ({
    x: ((id % width) + 0.5) * spacing,
    y: (Math.floor(id / width) + 0.5) * spacing,
