    if (!orders.has(id)) orders.set(id, order++);
    open.add(id);
    if (world.config.forest)
      queue.push({
        id,
        score: (scores.get(id) ?? Infinity) + v7Distance(position(id), goal),
        order: orders.get(id) ?? 0,
      });
