import { rootSpecimenVisible } from './long-root-visibility.js';
import {
  shortPublicObject,
  shortPublicStack,
} from './open-short-observation.js';
import type {
  V7Actor,
  V7Condition,
  V7Data,
  V7Observation,
  V7World,
} from './continuous-types.js';
import {
  v7Distance,
  v7ShapeDistance,
  v7Visible,
} from './continuous-geometry.js';
import { v7Clone } from './continuous-data.js';

export function v7Observe(world: V7World, id: string): V7Observation {
  const actor = world.actors.find((a) => a.id === id);
  if (!actor) throw new Error('Unknown observer.');
  const radius = world.config.vision;
  const terrain: V7Observation['terrain'] = [];
  for (let y = 0; y < world.config.height; y++)
    for (let x = 0; x < world.config.width; x++) {
      if (
        v7Distance(actor.position, { x: x + 0.5, y: y + 0.5 }) <= radius &&
        v7Visible(world, actor.position, { x: x + 0.5, y: y + 0.5 })
      )
        terrain.push({ x, y, kind: world.terrain[y]?.[x] ?? '?' });
    }
  return v7Clone({
    tick: world.tick,
    time: world.time,
    self: actor,
    actors: world.actors
      .filter(
        (a) =>
          a.id !== id &&
          v7Distance(actor.position, a.position) <= radius &&
          v7Visible(world, actor.position, a.position),
      )
      .map((a) => ({
        id: a.id,
        name: a.name,
        position: a.position,
        alive: a.vitals.health > 0,
      })),
    objects: world.objects
      .filter(
        (o) =>
          v7ShapeDistance(actor.position, o.spatial) <= radius &&
          (o.spatial.enclosure || v7Visible(world, actor.position, o.spatial)),
      )
      .map((o) =>
        world.config.forest
          ? {
              ...o,
              data: Object.fromEntries(
                Object.entries(o.data).filter(
                  ([key]) =>
                    [
                      'resource',
                      'stock',
                      'capacity',
                      'mode',
                      'species',
                      'contents',
                      'progress',
                      'elapsed',
                      'heating',
                      'insulation',
                      'light',
                    ].includes(key) ||
                    (o.kind === 'water-spill' &&
                      [
                        'cell',
                        'waterMl',
                        'clayMass',
                        'interpretation',
                      ].includes(key)) ||
                    (world.config.development &&
                      [
                        'stage',
                        'soil',
                        'health',
                        'group',
                        'offspring',
                        'fear',
                        'establishment',
                      ].includes(key)) ||
                    o.createdBy !== null,
                ),
              ),
            }
          : o,
      )
      .map(preservationPublicObject)
      .map(shortPublicObject),
    stacks: world.stacks
      .filter((s) => rootSpecimenVisible(world, s.id))
      .filter(
        (s) =>
          s.owner === id ||
          (s.owner === null &&
            v7Distance(actor.position, s.position) <= radius &&
            v7Visible(world, actor.position, s.position)),
      )
      .map((s) =>
        (world.state.foodAssessment === 1 && s.owner === id) ||
        (world.state.riverWater === 1 && s.owner === id && !s.reservedFor)
          ? { ...s, position: { ...actor.position } }
          : s,
      )
      .map((s) => {
        if (!s.physical && !s.materialLayer) return s;
        const visible = { ...s };
        delete visible.physical;
        delete visible.materialLayer;
        return preservationPublicStack(visible);
      })
      .map(shortPublicStack),
    terrain,
    events: world.events
      .filter((e) => rootSpecimenVisible(world, e.target))
      .filter(
        (e) =>
          e.actor === id ||
          (e.type === 'message' && e.target === id) ||
          (e.position &&
            v7Distance(actor.position, e.position) <= radius &&
            e.type !== 'message' &&
            v7Visible(world, actor.position, e.position)),
      )
      .map(preservationPublicEvent),
  });
}
export function v7Remember(world: V7World): void {
  for (const actor of world.actors) {
