    config: world.config,
    tick: world.tick,
    time: world.time,
    terrain: world.terrain,
    actors: world.actors.map((a) => ({
      id: a.id,
      vitals: a.vitals,
      wellbeing: a.wellbeing,
      ...(world.config.experience ? { experience: a.experience } : {}),
      ...(world.config.collective ? { collective: a.collective } : {}),
      mastered: a.mastered,
      learning: a.learning,
      position: a.position,
      radius: a.radius,
      parents: a.parents,
      bornAt: a.bornAt,
      life: a.life ?? null,
