    throw new Error(
      'Package installation cannot grant physical objects or processes; create them through paid execution.',
    );
  if (
    protectedState !==
    v7Signature({
      config: next.config,
      tick: next.tick,
      time: next.time,
      terrain: next.terrain,
      actors: next.actors.map((a) => ({
        id: a.id,
        vitals: a.vitals,
        wellbeing: a.wellbeing,
        ...(world.config.experience ? { experience: a.experience } : {}),
        ...(world.config.collective ? { collective: a.collective } : {}),
        mastered: a.mastered,
        learning: a.learning,
        position: a.position,
        radius: a.radius,
        parents: a.parents,
        bornAt: a.bornAt,
        life: a.life ?? null,
      })),
      stacks: next.stacks,
    })
  )
    throw new Error(
      'Migration changed protected goals, vitals, rewards, mastery, stock or run policy.',
