    revisions: world.revisions,
    interfaces: world.abilities,
    satisfactionSources: world.satisfaction,
    resources:
      world.config.forest && actorId
        ? world.resources
            .filter((r) => {
              const actor = world.actors.find((a) => a.id === actorId);
