    if (e.writes.some((id) => (counts.get(id) ?? 0) > 1)) {
      effects.delete(actor);
      feedback.set(actor, {
        outcome: 'resource-conflict',
        detail:
          'Concurrent transactions on the same resource were all rejected.',
        skillId: feedback.get(actor)?.skillId ?? null,
