            ...after,
            health: Math.max(
              0,
              after.health -
                (after.satiety === 0 ? EVOLUTION_CONFIG.starvationDamage : 0),
            ),
            satiety: Math.max(0, after.satiety - EVOLUTION_CONFIG.satietyLoss),
          };
