    f.lit ||
    weather.rain > 0.15 ||
    weather.wind > 0.65 ||
    f.lots.some((l) => l.moisture > 0.35)
  )
    throw new Error(
      'Ignition needs an unlit site, dry fuel, transmitted rain <= 0.15 and wind <= 0.65.',
