import type {
  V7Action,
  V7Actor,
  V7Cursor,
  V7World,
} from './continuous-types.js';
import { v7Clone, v7Signature, v7Json } from './continuous-data.js';
import {
  forestReferenceSpelling,
  FOREST_REFERENCE_SCOPES,
} from './forest-references.js';

type Operation = NonNullable<V7Cursor['operation']>;
