/** A plan is disposable; paid work and its exact resolved identity are not. */
export function forestBoundOperation(
  w: V7World,
  a: V7Actor,
  action: V7Action,
): Operation | null {
  if (w.state.operationContinuity !== 1 || a.vitals.health <= 0) return null;
