        { x: -vine.length / 2, y: 0.08, z: vine.diameter / 2 },
        { x: vine.length / 2, y: 0.08, z: vine.diameter / 2 },
      ];
  if (wrapped)
    points.push({ x: vine.length - circumference, y: 0, z: vine.diameter / 2 });
  paths.push({
    id: vine.id,
    source: vine.source,
    kind: vine.kind,
    diameter: vine.diameter,
    contourLength: vine.length,
    points,
  });
  return paths;
}

