    method: NUT_REV,
    sourceUnit: 1,
    contacts: m.contacts,
    covering: 'contact discontinuity',
    exposed: m.exposed,
    retainedAssembly: true,
    visibleRegion: m.exposed ? 0.2 : 0,
  };
