    sample = w.stacks.find((s) => s.id === d.sample);
  if (sample) {
    preservationReleaseSurface(w, sample);
    delete sample.reservedFor;
    sample.processing = {
      ...(sample.processing ?? {}),
      assayPartial: {
        process: p.id,
        readings: d.readings,
        paidEnergy: d.paid,
        reason,
        limitations: ASSAY_LIMIT,
