    dPhysical.opening = 1.1;
    dPhysical.tray = tray.id;
    const before = dPhysical.evaporated;
    preservationExchange(w, s);
    d.evaporated += dPhysical.evaporated - before;
    if (dPhysical.evaporated > before) d.dryingRounds++;
