  const ledger = (w.state['open:water-ledger'] ?? {}) as V7Data;
  ledger[p.id] = Number(ledger[p.id] ?? 0) + transferred;
  w.state['open:water-ledger'] = ledger;
  d.history.push({
    tick: w.tick,
    temperature: climate.temperature,
    humidity,
    evaporated: transferred,
  });
