      sample: V7Stack = {
        ...v7Clone(source),
        id: v7Id(w, 'item'),
        quantity,
        quantityTenths: foodTenths(quantity),
        owner: null,
        position: { x: tray.spatial.x, y: tray.spatial.y },
        reservedFor: id,
