  j.paid = d.paid;
  j.stage++;
  balance.data.service = Number(balance.data.service) - 0.1;
  if (d.initial < 0) d.initial = reading;
  d.lastReading = d.dryingRounds;
  const row = {
    tick: w.tick,
    relativeMass: v7RoundNumber(reading),
    resolution,
    reference: weight.id,
    dryingRounds: d.dryingRounds,
    paidEnergy: 0.5,
  };
