function owned(c: V7ActionContext, id: string) {
  const s = c.world.stacks.find(
    (s) => s.id === id && s.owner === c.actor.id && !s.reservedFor,
  );
  if (!s)
    throw new Error(
      'The exact owned unreserved contact specimen is unavailable.',
    );
