  c.emit(
    'contact-calibration-progress',
    'Inspected actual contact surfaces; model-derived geometry is not an independent absolute hardness anchor.',
    {
      project: j.id,
      mode: 'inspect',
      paidEnergy: 0.2,
      totalPaid: j.paid,
      observations,
      model: CONTACT_MODEL,
      absoluteBounds: null,
      remainingWork: 0,
    },
    target.id,
  );
