      inspections = (j.inspections ?? []) as V7Data[];
    if (
      surfaces.some(
        (s) =>
          !s.controlledContact ||
          !inspections.some(
            (r) =>
              r.specimen === s.specimen &&
              r.edgeRadius === s.edgeRadius &&
              r.wear === s.wear,
          ),
      )
