        'contact-calibration-invalidated',
        'Insufficient actual geometry; no second edge, contact or absolute bound was produced.',
        {
          project: j.id,
          surfaces,
          paidEnergy: 0,
          remainingWork: 6,
          absoluteBounds: null,
        },
        first.id,
