    j.specimens = [];
    j.stage = 0;
    j.observations = [];
    j.x = a.position.x;
    j.y = a.position.y;
    j.status = 'active';
    j.tests = 1;
    j.evidenceRoots = [first, second].map((s) => `${s.origin}:${s.resource}`);
    scratchReserve(c, j, first, contactKey(a.id, j.id));
    scratchReserve(c, j, second, contactKey(a.id, j.id));
    a.extensionState['open:contact-work'] = j.id;
