    cup: arm.cup,
    tissue: arm.tissue,
    liquid: arm.liquid,
    contactRounds: arm.contactRounds,
    leakedSolids: arm.leakedSolids,
    separated: arm.separated,
    waterMl: w.stacks.find((s) => s.id === arm.cup)?.waterCup?.waterMl ?? null,
    limitation: EXTRACTION_LIMIT,
  }));
}

