    ...v7Clone(source),
    id: v7Id(c.world, 'item'),
    resource: 'extraction-material',
    quantity: 1,
    quantityTenths: 10,
    reservedFor: key,
    physical: {
      unitMass: p.unitMass * q,
      unitWater: p.unitWater * q,
      unitSolids: p.unitSolids * q,
