/** Transfer tracked constituents; no nutrient/toxin inference, destruction or creation. */
export function extractionTransfer(
  from: V7Stack,
  to: V7Stack,
  solid: number,
  water = 0,
) {
  if (
    !from.physical ||
    !to.physical ||
    solid < 0 ||
    water < 0 ||
    solid > from.physical.unitSolids + 1e-9 ||
    water > from.physical.unitWater + 1e-9
