    version: 1,
    resistance: r.properties?.hardness ?? 0,
    edgeRadius: 0.001 / Math.max(1, r.properties?.hardness ?? 0),
    wear: 0,
    fractured: damage,
    contaminated: !!s.processing?.gravimetricAssay,
