    specimen: s.id,
    origin: s.origin,
    surface: `${s.id}:contact-surface`,
    edgeRadius: Number(p.edgeRadius),
    wear: Number(p.wear),
    fractured: p.fractured === true,
    contaminated: p.contaminated === true,
    controlledContact: p.usable === true,
