    scratchReserve(c, j, reference);
    a.extensionState['open:hardness-work'] = j.id;
    w.processes.push({
      id: v7Id(w, 'process'),
      handler: 'open.hardness-cleanup',
      owner: a.id,
      object: null,
      next: w.tick + 1,
      revision: 'hardness-assessment@1',
      data: { project: j.id },
    });
  }
  const specimens = j.specimens.map((id) =>
    w.stacks.find((s) => s.id === id && s.owner === a.id),
  );
