    throw new Error('Actual reserved contact specimens are missing.');
  if (a.vitals.energy < 0.5)
    return { complete: false, remaining: 2 - j.stage, writes: [] };
  if (specimens.some((s) => !s || scratchPhysical(w, s).usable !== true))
    return { complete: false, remaining: 2 - j.stage, writes: [] };
