import type {
  V7World,
  V7Stack,
  V7Data,
  V7Package,
} from './continuous-types.js';
import { foodUnitMass } from './forest-food-accounting.js';
import { v7Clone } from './continuous-data.js';
export interface PoleShape extends V7Data {
  unit: string;
  source: string;
  slot: number;
  seed: number;
  version: number;
  length: number;
  diameter: number;
  taper: number;
  curvature: number;
  defects: number;
  density: number;
  modulus: number;
  strength: number;
  unitMass: number;
  water: number;
  solid: number;
  provenance: string;
}
const allocationKey = (id: string) => `geometry:allocation:${id}`;
