          throw new Error(
            'Resume/cancel use only the exact project; unused arguments must be empty or zero.',
          );
      }
      if (mode === 'cancel') {
        const j = metrologyRecord(
          c.world,
          c.actor,
          v7String(c.action.args.project, 'project'),
