import type { V7Object, V7Stack, V7Event } from './continuous-types.js';
/** Public appearance and bookkeeping are distinct from the raw physical audit. */
export function preservationPublicObject(o: V7Object): V7Object {
  const d = o.data.preservation;
  if (!d || typeof d !== 'object' || Array.isArray(d)) return o;
  return {
    ...o,
    data: {
      ...o.data,
      preservation: {
        ...d,
        waterFraction: Math.round(Number(d.waterFraction) * 4) / 4,
        massRatio: Math.round(Number(d.massRatio) * 4) / 4,
        precision:
          'Coarse visual appearance, not a calibrated mass or moisture measurement.',
      },
    },
  };
}
export function preservationPublicStack(s: V7Stack): V7Stack {
  const p = s.processing,
    d = p?.preservationPhysics;
  if (!p || !d || typeof d !== 'object' || Array.isArray(d)) return s;
  const input = p.preservationInput;
  const publicInput =
    input && typeof input === 'object' && !Array.isArray(input)
      ? Object.fromEntries(
          Object.entries(input).filter(
            ([key]) => !['nutrition', 'toxins'].includes(key),
          ),
        )
      : null;
  return {
    ...s,
    processing: {
      ...p,
      preservationPhysics: {
        version: d.version ?? null,
        prepared: d.prepared ?? false,
        tray: d.tray ?? '',
        opening: d.opening ?? 1,
        initialization: d.initialization ?? '',
        condition:
          'Exact water and nutrient/toxin totals are physical audit state; paid evidence is recorded separately.',
      },
      ...(publicInput ? { preservationInput: publicInput } : {}),
    },
  };
}
export function preservationPublicEvent(e: V7Event): V7Event {
  if (e.type !== 'preservation-progress' || !('audit' in e.data)) return e;
  const data = Object.fromEntries(
    Object.entries(e.data).filter(([key]) => key !== 'audit'),
  );
  return { ...e, data };
}

import type { V7Data, V7Object, V7Stack, V7World } from './continuous-types.js';
import { v7RoundNumber } from './continuous-data.js';
import { forestClimate, forestEvent } from './forest-climate.js';
import { refugeRay } from './open-shelter-geometry.js';
import { v7ShapeDistance, v7ShapesOverlap } from './continuous-geometry.js';
export interface PreservationPhysics extends V7Data {
  version: number;
  initialWaterFraction: number;
  initialUnitMass: number;
  opening: number;
  prepared: boolean;
  tray: string;
  area: number;
  evaporated: number;
  absorbed: number;
  rainAdded: number;
  lastTick: number;
  baselineDeterioration: number;
  actualDeterioration: number;
  history: V7Data[];
  contamination: string;
  initialization: string;
}
export function preservationPhysics(s: V7Stack): PreservationPhysics | null {
  const d = s.processing?.preservationPhysics;
  return d && typeof d === 'object' && !Array.isArray(d) && d.version === 1
    ? (d as PreservationPhysics)
    : null;
}
export function preservationInitialize(
  w: V7World,
  s: V7Stack,
): PreservationPhysics {
  const old = preservationPhysics(s);
  if (old) return old;
  const r = w.resources.find((r) => r.id === s.resource);
  if (!r || r.nutrition <= 0) throw new Error('Actual food is required.');
  const represented = !!s.physical;
  if (!s.physical) {
    const fraction =
      s.resource === 'berry' ? 0.85 : s.resource === 'root' ? 0.75 : null;
    if (fraction === null)
      throw new Error(
        'Composition is unrepresented; no drying composition is invented.',
      );
    s.physical = {
      unitMass: r.mass,
      unitWater: r.mass * fraction,
      unitSolids: r.mass * (1 - fraction),
    };
  }
  const d: PreservationPhysics = {
    version: 1,
    initialWaterFraction: s.physical.unitWater / s.physical.unitMass,
    initialUnitMass: s.physical.unitMass,
    opening: 1,
    prepared: false,
    tray: '',
    area: 0,
    evaporated: 0,
    absorbed: 0,
    rainAdded: 0,
    lastTick: -1,
    baselineDeterioration: 0,
    actualDeterioration: 0,
    history: [],
    contamination: 'Unresolved; drying never sterilizes or removes toxins.',
    initialization: represented
      ? 'Retained existing represented composition; not a new measurement.'
      : 'Version-1 berry/root water fraction is a physical-model assumption, not measured evidence.',
  };
