    const { load, loadMargin: margin, sound } = refugeLoads(w, o);
    if (!sound) {
      o.data.proven = false;
      o.visual.state = 'failed';
      forestEvent(
        w,
        'shelter-damaged',
        'Actual wet loading, wear or wind exceeded the proven margin; overhead coverage is removed.',
        o.spatial,
        null,
        { load, margin, condition: o.data.condition },
        o.id,
      );
    }
  }
  p.next = w.tick + 1;
}

