import { v7Distance } from './continuous-geometry.js';
import { forestEvent } from './forest-climate.js';
export interface RefugeWork extends V7Data {
  id: string;
  owner: string;
  mode: string;
  status: string;
  stage: number;
  total: number;
  paid: number;
  x: number;
  y: number;
  angle: number;
  escrow: string[];
