  const provenance = (contents.provenance ?? []) as {
    source: string;
    ml: number;
    first: number;
    last: number;
  }[];
  const prior = provenance.find((p) => p.source === lineage.source);
  if (prior) {
    prior.ml += ml;
    prior.last = w.tick;
  } else
    provenance.push({
      source: lineage.source,
      ml,
      first: w.tick,
      last: w.tick,
    });
