    const pieces: V7Stack[] = [0.1, 0.1, 0.2, 0.2, 0.4].map((quantity) => ({
      ...original,
      id: v7Id(w, 'item'),
      quantity,
      quantityTenths: foodTenths(quantity),
      owner: a.id,
      position: { ...a.position },
      processing: {
        comparisonWeight: {
          balance: balance.id,
          source: original.id,
          paidEnergy: 1,
        },
      },
    }));
    for (const p of pieces) {
      delete p.reservedFor;
      w.stacks.push(p);
    }
    j.components = j.components.filter((p) => p !== stone);
    j.weights = pieces.map((p) => p.id);
