    {
      project: j.id,
      stage: j.stage,
      remainingWork: 17 - j.stage,
      paidEnergy: j.paid,
      balance: balance.id,
      mesh: mesh.id,
      apertures: j.apertures ?? null,
    },
    balance.id,
  );
  return {
    complete: j.stage === 14,
    remaining: Math.max(0, 14 - j.stage),
    writes: [balance.id, mesh.id],
  };
}

