        key,
        subject: balance.id,
        property: 'working comparison range',
        value: {
          history,
          resolution: 0.05,
          safeWorkingLoad: balance.data.safeWorkingLoad ?? 0,
        },
        method: 'paid zero, exchange and repeated retained-load comparison',
        condition: 'current actual geometry and tare',
        verified: true,
      });
