  t: V7Object,
  s: V7Stack,
  quantity: number,
): { reason: string | null; diameter: number; aperture: number } {
  if (b.data.variant !== 'woven' && t.data.variant !== 'woven')
    return { reason: null, diameter: 0, aperture: 0 };
