    lawVersion: 1,
    resource: s.resource,
    origin: s.origin,
    length: law.length,
    diameter: 2 * radius,
    mass,
    appliedForce: force,
    wetness: wet,
    deflection,
    creep: slip,
    passed,
    safeWorkingLoad: passed ? force * scale * 0.25 : 0,
    uncertainty: 0.5,
