  );
  const costs = instructions.map((i) =>
    i.op === 'consume'
      ? `Consume ${String(i.quantity)} target units.`
      : i.op === 'harvest'
        ? `Remove ${String(i.quantity)} ${i.kind} stock; timber/fish consume one tool durability per unit.`
