      name: 'Dry branch',
      appearance: 'Short dry wooden branch',
      nutrition: 0,
      toxicity: 0,
      durability: 0,
    },
    {
      id: 'stone',
      name: 'Loose stone',
      appearance: 'Palm-sized rough stone',
      nutrition: 0,
      toxicity: 0,
      durability: 0,
    },
  ];
  const stacks: EStack[] = [];
  const ground = (
    id: string,
    type: string,
    x: number,
    y: number,
    quantity = 1,
  ) =>
    stacks.push({
      id,
      type,
      quantity,
      durability: 0,
      owner: null,
      position: { x, y },
