      if (!parts.length) return v;
      if (from < v.length) parts.push(v.slice(from));
      return { $join: parts };
    }
    if (Array.isArray(v)) return v.map(visit);
    if (v && typeof v === 'object')
      return Object.fromEntries(
        Object.entries(v).map(([k, cell]) => [k, visit(cell)]),
      );
    return v;
  };
  return visit(value);
}
