export function openKeyWire(text: string): string {
  const raw: unknown = JSON.parse(text);
  if (
    !raw ||
    typeof raw !== 'object' ||
    !('encoding' in raw) ||
    raw.encoding !== 'lossless-shared-values-v5' ||
    !('recordColumns' in raw) ||
    !Array.isArray(raw.recordColumns) ||
    !('shared' in raw) ||
    !Array.isArray(raw.shared) ||
    !('payload' in raw)
  )
    return text;
