    if (Array.isArray(v)) v.forEach(count);
    else if (v && typeof v === 'object')
      for (const [key, cell] of Object.entries(v)) {
        countKey(key);
        if (key === '$t') {
          const [columns, rows] = cell as [string[], unknown[][]];
          columns.forEach(countKey);
          rows.forEach(count);
        } else count(cell);
      }
