        const value = raw.observed;
        if (
          !value ||
          typeof value !== 'object' ||
          Array.isArray(value) ||
          !Array.isArray(value.blockers)
        )
          continue;
        for (const b of value.blockers) {
          if (!b || typeof b !== 'object' || Array.isArray(b)) continue;
          const at = b.spatial;
          if (
            !at ||
            typeof at !== 'object' ||
            Array.isArray(at) ||
            typeof at.x !== 'number' ||
            typeof at.y !== 'number'
          )
            continue;
          c.save();
