          c.lineTo(at.x + 0.12, at.y + 0.12);
          c.moveTo(at.x + 0.12, at.y - 0.12);
          c.lineTo(at.x - 0.12, at.y + 0.12);
          c.stroke();
          c.restore();
        }
      }
  }
