    c.setLineDash([0.18, 0.1]);
    c.strokeRect(-1, -1, 2, 2);
    for (const px of [-0.85, 0.85]) {
      c.beginPath();
      c.moveTo(px, 0.85);
      c.lineTo(px, -0.85);
      c.stroke();
    }
