        wall.shape.height,
      );
      c.strokeStyle = '#293b32';
      c.lineWidth = 0.07;
      c.strokeRect(
        -wall.shape.width / 2,
        -wall.shape.height / 2,
        wall.shape.width,
        wall.shape.height,
