      c.lineTo(0.3, -0.4);
      c.lineTo(0.17, -0.47);
      c.moveTo(0.3, -0.3);
      c.lineTo(0.43, -0.43);
      c.stroke();
    }
  } else if (o.kind === 'rock') {
    c.fillStyle = o.visual.color;
    c.beginPath();
    c.moveTo(-0.4, 0.1);
    c.lineTo(-0.32, -0.3);
    c.lineTo(0.05, -0.48);
    c.lineTo(0.39, -0.22);
    c.lineTo(0.43, 0.19);
    c.lineTo(-0.1, 0.28);
    c.closePath();
    c.fill();
    c.strokeStyle = '#c7c9b3';
    c.lineWidth = 0.04;
    c.stroke();
  } else {
    const stock = Number(o.data.stock ?? 1);
    for (let n = 0; n < 5; n++)
      ellipse(
        c,
        Math.cos(n * 2.4) * 0.2,
