  const beneathClosedRoof = (point: { x: number; y: number }): boolean =>
    frame.objects.some(
      (o) =>
        o.spatial.enclosure &&
        v7Interior(point, o.spatial) &&
        (!self || !v7Interior(self.position, o.spatial)),
