.events-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 20px 0 8px;
}
.events-head h3 {
  font:
    500 20px 'Fraunces',
    Georgia,
    serif;
  margin: 0;
}
.event-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.event-entry {
  text-align: left;
  min-width: 0;
  background: #f4f6ec;
  border: 1px solid #d2d9ca;
  padding: 12px;
  border-radius: 9px;
  font-size: 12px;
  line-height: 1.5;
  overflow-wrap: anywhere;
