  flex-direction: column;
  gap: 14px;
  padding-top: 2px;
}
.observer-card {
  background: #f7f8f1;
  border: 1px solid #cdd6c6;
  border-radius: 13px;
  padding: 18px;
}
.observer-card h3 {
  font:
    500 21px 'Fraunces',
    Georgia,
    serif;
  margin: 4px 0 12px;
}
.observer-card p {
  font-size: 12px;
  line-height: 1.65;
  color: #5d705f;
  overflow-wrap: anywhere;
}
.actor-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.actor-heading select {
  max-width: 120px;
}
.coordinates {
  font-size: 11px;
  color: #73846e;
