  color: #7a886e;
}
.vitals {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 18px;
}
.vital-label {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  margin-bottom: 5px;
}
.vital-track {
  height: 4px;
  background: #e2e7da;
  border-radius: 3px;
  overflow: hidden;
}
.vital-fill {
  height: 100%;
  background: #648d70;
}
.memory-list {
  padding-left: 15px;
  color: #5d705f;
  font-size: 12px;
  line-height: 1.6;
  margin: 8px 0;
}
.source-row {
