  font-size: 12px;
  color: #6f7c67;
  padding: 12px 32px;
  min-height: 32px;
}
.obs-status.error {
  color: #9f4e37;
}
.event-active {
  animation: event-emphasis 0.7s ease-out;
}
.event-rest,
.event-eat {
  animation: actor-emphasis 0.7s ease-out;
}
@keyframes event-emphasis {
  from {
    opacity: 0.35;
  }
  to {
    opacity: 1;
  }
}
@keyframes actor-emphasis {
  50% {
    filter: brightness(1.25);
  }
}
@media (max-width: 1050px) {
  .obs-layout {
    grid-template-columns: minmax(380px, 1fr) 285px;
    padding: 16px;
  }
  .obs-header {
    padding: 18px;
  }
  .header-controls a {
    display: none;
  }
  .header-controls #ashen-link {
    display: inline;
    font-size: 10px;
  }
  .observer-card {
    padding: 15px;
  }
  .event-list {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 750px) {
  .obs-layout {
    display: block;
  }
  .obs-aside {
    margin-top: 18px;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .world-toolbar {
    flex-wrap: wrap;
  }
  .obs-header {
    height: auto;
    gap: 10px;
    align-items: flex-start;
  }
  .header-controls {
    flex-direction: column;
  }
  .brand h1 {
    font-size: 19px;
  }
  .brand-mark {
    display: none;
  }
  .world-stage {
