    min-height: 420px;
  }
  .event-list {
    grid-template-columns: 1fr;
  }
  .observer-card {
    min-width: 0;
  }
  .minimap {
    width: 105px;
    height: 105px;
  }
  .camera-tools {
    top: 50px;
  }
  .stage-caption {
    max-width: 60%;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
  }
}

.camera-tools button[aria-pressed='true'] {
  background: #315b45;
  color: #fff5dd;
}
@media (max-width: 750px) {
  .playback {
    flex-wrap: wrap;
  }
  .playback input {
    order: 2;
    flex-basis: 100%;
  }
  .round-value {
    min-width: 0;
    flex: 1;
    text-align: center;
  }
  .obs-aside {
    grid-template-columns: 1fr;
  }
  .header-controls select {
    max-width: 140px;
  }
  .brand {
    min-width: 0;
  }
  .brand h1 {
    font-size: 18px;
  }
  .brand p {
    font-size: 10px;
  }
}

.scene-object,
.scene-actor {
  outline: none;
}
.scene-object:focus-visible,
.scene-actor:focus-visible {
  filter: brightness(1.3) drop-shadow(0 0 0.08px #fff4c6);
}

.inventory-heading {
  margin-top: 18px;
}
.carried-items {
  margin-top: 8px;
  font-size: 12px;
  color: #60725e;
  line-height: 1.6;
}
details summary {
  font-size: 11px;
  color: #6d7e65;
  cursor: pointer;
}

#forest-scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.forest-hit-regions {
