  border-collapse: collapse;
  font-size: 11px;
}
.trial-diagnostic caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 8px;
}
.trial-diagnostic td,
.trial-diagnostic th {
  padding: 5px 3px;
  border-bottom: 1px solid #455549;
  text-align: left;
  vertical-align: top;
}

