export interface Sprite {
  image: HTMLCanvasElement;
  x: number;
  y: number;
  width: number;
  height: number;
  foot: number;
}
export interface Art {
  trees: Sprite;
  rock: Sprite;
  herb: Sprite;
  pebbles: Sprite;
