    c.fillStyle = '#20302222';
    c.fillRect(0, 0, width, height);
    const poses = this.poses;
    const drawables: { y: number; draw: () => void }[] = [];
    this.hits = [];
    this.labels = [];
    for (const o of world.objects) {
      const pos = p(o.spatial);
      if (
        pos.x < -300 ||
        pos.x > width + 300 ||
        pos.y < -120 ||
        pos.y > height + 300
      )
        continue;
      if (o.spatial.enclosure) {
        this.building(c, o, world, scale, p);
        continue;
      }
      drawables.push({
        y: o.spatial.y,
        draw: () => {
          this.object(c, o, scale, p);
        },
      });
    }
    for (const a of world.actors) {
      const job = data(a.extensionState['shelter:pending']);
      if (
        job &&
        typeof job.x === 'number' &&
        typeof job.y === 'number' &&
        job.mode === 'build'
      ) {
        const point = p({ x: job.x, y: job.y }),
          paid = Number(job.elapsed ?? 0);
        c.save();
        c.translate(point.x, point.y);
        c.scale(scale, scale * DEPTH);
        c.rotate(Number(job.angle ?? 0));
        c.fillStyle = '#b99f6455';
        c.fillRect(-1, -1, 2, 2);
        c.strokeStyle = '#dec59b';
        c.lineWidth = 0.025;
        c.setLineDash([0.1, 0.1]);
        c.strokeRect(-1, -1, 2, 2);
        c.setLineDash([]);
        c.strokeStyle = '#c8a06b';
        c.lineWidth = 0.08;
        for (let n = 0; n < Math.min(6, paid); n++) {
          c.beginPath();
          c.moveTo(-0.9 + n * 0.32, 0.85);
          c.lineTo(-0.9 + n * 0.32, -0.85);
          c.stroke();
        }
        c.restore();
        this.labels.push({
          x: point.x,
          y: point.y - 1.2 * scale,
          text: `Under construction · ${String(paid)}/6`,
          color: '#ead0a1',
        });
      }
    }
    for (const e of world.events.filter(
      (e) =>
        ['site-examination-completed', 'join-geometry-assessed'].includes(
          e.type,
        ) && e.success,
    )) {
      if (typeof e.data.x !== 'number' || typeof e.data.y !== 'number')
        continue;
      const point = p({ x: e.data.x, y: e.data.y });
      if (e.type === 'join-geometry-assessed')
        this.labels.push({
          x: point.x,
          y: point.y - 10,
          text: 'Join geometry unresolved',
          color: '#d3c49e',
        });
      c.save();
      c.strokeStyle = '#d6be87bb';
      c.lineWidth = 2;
      c.setLineDash([3, 3]);
      c.beginPath();
      c.ellipse(
        point.x,
        point.y,
        scale * 0.2,
        scale * 0.2 * DEPTH,
        0,
        0,
        Math.PI * 2,
      );
      c.stroke();
      c.restore();
    }
    for (const s of world.stacks.filter(
      (s) =>
        !s.owner &&
        s.quantity > 0 &&
        rootSpecimenVisible(world, s.id) &&
        !joiningContains(world.objects, s),
    )) {
      const pos = p(s.position);
      drawables.push({
        y: s.position.y,
        draw: () => {
          this.shadow(c, pos.x, pos.y, scale * 0.18);
          c.fillStyle =
            world.resources.find((r) => r.id === s.resource)?.color ??
            '#d4bf8a';
          if (
            s.processing?.method === 'source-bound-hazelnut-opening-trial@1'
          ) {
            // A minimum-size observation glyph, not a fabricated detached kernel.
            const radius = Math.max(3.5, scale * 0.025);
            c.beginPath();
            c.ellipse(pos.x, pos.y, radius, radius * 0.8, 0, 0, Math.PI * 2);
            c.fill();
            c.strokeStyle =
              s.processing.exposed === true ? '#d8bd91' : '#3a291f';
            c.lineWidth = s.processing.exposed === true ? 2 : 1;
            c.beginPath();
            c.moveTo(pos.x - radius / 2, pos.y - radius / 3);
            c.lineTo(pos.x, pos.y);
            c.lineTo(pos.x + radius / 2, pos.y - radius / 3);
