    const labels = world.config.longDevelopment
      ? labelRows(
          this.labels.map((label) => ({
            ...label,
            width: c.measureText(label.text).width + 18,
          })),
        )
      : this.labels;
    for (const label of labels)
      this.label(c, label.x, label.y, label.text, label.color);
