import { BOOKMARKS } from './ex9/bookmarks.js';
export type Story = {
  experiment: 'ex9' | 'ex13';
  title: string;
  initialRound: number;
  bookmarks: typeof BOOKMARKS;
};
export function presentationExperiment(search: string): Story['experiment'] {
  return new URLSearchParams(search).get('experiment') === 'ex13'
    ? 'ex13'
    : 'ex9';
}
export function parseStory(value: unknown): Story {
  if (!value || typeof value !== 'object')
    throw new Error('Missing recorded story metadata.');
  const story = value as Story;
  if (
    story.experiment !== 'ex13' ||
    typeof story.title !== 'string' ||
    !Number.isSafeInteger(story.initialRound) ||
    story.initialRound < 0 ||
    !Array.isArray(story.bookmarks) ||
    story.bookmarks.length > 12 ||
    story.bookmarks.some(
      (b) =>
        !Number.isSafeInteger(b.tick) ||
        b.tick < 0 ||
        !['lin', 'moss', 'sol'].includes(b.actor) ||
        !['lin', 'moss', 'sol'].includes(b.sourceActor) ||
        [b.title, b.text, b.type].some((s) => typeof s !== 'string'),
    )
  )
    throw new Error('Invalid recorded story metadata.');
  return story;
}
export async function presentationStory(
  experiment: Story['experiment'],
): Promise<Story> {
  if (experiment === 'ex9')
    return {
      experiment,
      title: 'EX9 · Real experiment replay · Visual enhancement',
      initialRound: 79,
      bookmarks: BOOKMARKS,
    };
  const response = await fetch(`./presentation/${experiment}/story.json`);
  if (!response.ok)
    throw new Error(
      'This observation has no published presentation evidence yet.',
    );
  return parseStory((await response.json()) as unknown);
}

apps/viewer/src/replay-client.ts:
import type { ReplayRequest, ReplayResponse } from './replay-service.js';

type FrameResponse = Extract<ReplayResponse, { kind: 'frame' }>;
type WorkerPort = Pick<
  Worker,
  'postMessage' | 'terminate' | 'onmessage' | 'onerror' | 'onmessageerror'
>;

/** The main thread receives only the requested verified world, never a segment
 * or every intermediate frame. Superseded consumers settle without stale output. */
export class ReplayClient {
  private serial = 0;
  private failure: Error | undefined;
  private pending:
    | {
        id: number;
        resolve: (value: FrameResponse | null) => void;
        reject: (error: Error) => void;
        progress: (tick: number) => void;
      }
    | undefined;
  constructor(private readonly worker: WorkerPort) {
    worker.onmessage = (event: MessageEvent<ReplayResponse>) => {
      const response = event.data;
      const pending = this.pending;
      if (!pending || response.id !== pending.id) return;
      if (response.kind === 'progress') pending.progress(response.tick);
      else {
        this.pending = undefined;
        if (response.kind === 'error')
          pending.reject(new Error(response.message));
        else pending.resolve(response);
      }
    };
    const failed = () => {
      this.failure = new Error(
        'Replay worker failed. Reload the archive to retry.',
      );
      this.pending?.reject(this.failure);
      this.pending = undefined;
      worker.terminate();
    };
    worker.onerror = failed;
    worker.onmessageerror = failed;
  }
  seek(
    request: Omit<ReplayRequest, 'id'>,
    progress: (tick: number) => void,
  ): Promise<FrameResponse | null> {
    if (this.failure) return Promise.reject(this.failure);
    this.pending?.resolve(null);
    return new Promise((resolve, reject) => {
      const id = ++this.serial;
      this.pending = { id, resolve, reject, progress };
      this.worker.postMessage({ ...request, id } satisfies ReplayRequest);
    });
  }
  dispose(): void {
    this.pending?.resolve(null);
    this.pending = undefined;
    this.failure = new Error('Replay worker closed.');
    this.worker.terminate();
  }
}

apps/viewer/src/replay-playback.ts:
/** Playback has one outstanding seek. Slow verification never accumulates
 * timer requests that supersede frames before they can be displayed. */
export function replayPlayback(
  step: () => Promise<boolean>,
  changed: (playing: boolean) => void,
  delay = 900,
) {
  let generation = 0;
  let playing = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let inFlight: Promise<boolean> | undefined;
  function stop(): void {
    generation++;
    playing = false;
    clearTimeout(timer);
    changed(false);
  }
  function start(): void {
    if (playing) return;
    playing = true;
    changed(true);
    const token = ++generation;
    const advance = async (): Promise<void> => {
      try {
        if (inFlight) await inFlight;
        if (token !== generation) return;
        const current = step();
        inFlight = current;
        let more: boolean;
        try {
          more = await current;
        } finally {
          if (inFlight === current) inFlight = undefined;
        }
        if (token !== generation) return;
        if (!more) stop();
        else
          timer = setTimeout(() => {
            void advance();
          }, delay);
      } catch {
        if (token === generation) stop();
      }
    };
    timer = setTimeout(() => {
      void advance();
    }, delay);
  }
  return {
    start,
    stop,
    get playing() {
      return playing;
    },
  };
}

apps/viewer/src/replay-service.ts:
import {
  browserDigest,
  incrementalSceneReplay,
  ReplaySuperseded,
} from './continuous-history.js';
import type { SceneIndex, SceneSegment } from './continuous-history.js';
import type { V7Cursor, V7World } from '@self-evolving-world/world-core';

export interface ReplayRequest {
  id: number;
  url: string;
  part: SceneIndex['segments'][number];
  tick: number;
}
export type ReplayResponse =
  | { id: number; kind: 'progress'; tick: number }
  | {
      id: number;
      kind: 'frame';
      world: V7World;
      tasks: Record<string, V7Cursor>;
    }
  | { id: number; kind: 'error'; message: string };

/** One archive-owned worker. Both bytes and verified prefixes share a bounded
 * cache. Later requests supersede earlier work at verified round boundaries. */
export function replayService(
  load: (url: string) => Promise<string>,
  send: (response: ReplayResponse) => void,
  yieldTurn: () => Promise<void>,
) {
  let latest = 0;
  const cache = new Map<
    string,
    Promise<{
      segment: SceneSegment;
      replay: ReturnType<typeof incrementalSceneReplay>;
    }>
  >();
  async function seek(request: ReplayRequest): Promise<void> {
    latest = request.id;
    const current = () => latest === request.id;
    try {
      const { part } = request;
      const key = JSON.stringify([
        request.url,
        part.start,
        part.end,
        part.sha256,
      ]);
      let loading = cache.get(key);
      if (!loading) {
        loading = (async () => {
          const text = await load(request.url);
          if ((await browserDigest(text)) !== part.sha256)
            throw new Error('Segment integrity check failed.');
          const segment = JSON.parse(text) as SceneSegment;
          if (
            segment.start !== part.start ||
            segment.start + segment.rounds.length !== part.end
          )
            throw new Error('Replay segment bounds differ from its index.');
          return { segment, replay: incrementalSceneReplay(segment) };
        })();
      }
      // Refresh access order, including in-flight requests.
      cache.delete(key);
      cache.set(key, loading);
      if (cache.size > 3) cache.delete(cache.keys().next().value ?? '');
      const value = await loading;
      if (!current()) return;
      const world = await value.replay.frame(request.tick, {
        current,
        advanced: async (tick) => {
          if (current()) send({ id: request.id, kind: 'progress', tick });
          // WebCrypto can resolve within one task. Explicitly yield so worker
          // messages can cancel a long seek instead of queuing behind it.
          await yieldTurn();
        },
      });
      if (current())
        send({
          id: request.id,
          kind: 'frame',
          world,
          tasks:
            value.segment.rounds.find((r) => r.tick === request.tick)?.tasks ??
            {},
        });
    } catch (error) {
      if (current() && !(error instanceof ReplaySuperseded))
        send({
          id: request.id,
          kind: 'error',
          message: error instanceof Error ? error.message : 'Replay failed.',
        });
    }
  }
  return { seek };
}

