      expect(
        w.stacks.find((s) => s.id === 'fixture-branch')?.quantity,
      ).toBeCloseTo(4 - quantity * 2, 7);
      expect(v7TaskAction(w, 'ash-1', cursors['ash-1'])).toBeNull();
