    ).toBe(false);
    expect(
      rootStep(surfaceFixture(), {
        ...assessSurface,
        interface: 'root-preparation',
      }).outcomes['ash-1']?.success,
    ).toBe(true);
    const legacy = rootStep(rootFixture(), crush).world,
      upgraded = v7Clone(
