    ['dry-grass', 1],
  ].map(([r, n]) => ({
    id: 'fixture-' + String(r),
    resource: String(r),
    quantity: Number(n),
    owner: 'lin',
    position: { x: 10, y: 10 },
    origin: 'isolated-material-fixture',
