  let r = v7Step(
    w,
    {
      lin: fireWait,
      moss: fireWait,
      sol: fireWait,
      [id]: { interface: 'learn', args: { ability: 'tend-fire' } },
    },
    fireRegistry,
  );
  for (let n = 1; n < 6; n++)
    r = v7Step(
      r.world,
      { lin: fireWait, moss: fireWait, sol: fireWait },
      fireRegistry,
    );
