    if (i === 1 || i === 3) frames.push(v7Clone(w));
  }
  const o = w.objects.find((o) => o.kind === 'short-refuge');
  if (!o) throw new Error('No actual canopy.');
  for (let i = 0; i < 2; i++)
    w = shortAdvance(
      w,
      shortAction(
        'proof-test',
        'proof',
        [{ item: 'short-weight', quantityTenths: 1, role: 'load' }],
