      v7FinishTasks(w, result, cursors);
      w = v7Clone(result.world);
      expect(cursors.lin.cycle).toBe(i === 5 ? 1 : 0);
      if (i < 5) expect(cursors.lin.operation?.remaining).toBe(5 - i);
      if (i === 2) {
