  w = v7Clone(
    step(w, {
      interface: 'gather',
      args: { target: 'forest-moss-2', quantity: 1 },
    }).world,
  );
  const s = w.stacks.find((s) => s.resource === 'moss' && s.owner === 'sol');
  if (!s) throw new Error('Missing actually gathered sample');
  const action: V7Action = {
    interface: id,
    args: {
      mode: 'begin',
