  expect(recovery.world.actors[2]?.learning?.remaining).toBe(1);
  expect(step(recovery.world, wait).world.actors[2]?.mastered).toContain(id);
  expect(
    continuousRegistry(initialLongWorld('another-run')).packages.some(
      (p) => p.id === id,
    ),
  ).toBe(false);
});

