}
const ids = (
  capture ? [capture] : (browserSelection()?.archives ?? experimentIds(root))
)
  .filter(
    (id) =>
      (
        JSON.parse(
          readFileSync(
            resolve(root, 'experiment', id, 'manifest.json'),
            'utf8',
          ),
        ) as { version: number }
