} from '../apps/simulator/src/continuous-run.js';

export const OPEN_OBJECTIVE =
  'Observe early cumulative open development in one fresh three-actor world for a target 1600 rounds under fixed policy and 650/60/20 attempt budgets. Grounded questions, dependent capabilities and non-survival experiences are observations, not mandatory inventions or evidence of inevitable civilization.';
export function measureOpen(
  state: V7Execution,
  frames: V7World[],
  rounds: V7RoundRecord[],
) {
  const world = state.world,
    events = rounds.flatMap((r) => r.events);
  const packages = continuousRegistry(world).packages.filter((p) =>
    world.revisions.includes(`${p.id}@${String(p.version)}`),
  );
  return {
    evidence: openEvidence(frames, rounds),
    inheritSkills: world.config.development?.inheritSkills,
    scope: world.config.development?.scope,
    authoredBaseline: world.config.development?.baseline,
    initialRevisions: frames[0]?.revisions,
    implementations: packages
      .filter((p) => p.scope)
      .map((p) => ({
        package: `${p.id}@${String(p.version)}`,
        scope: p.scope,
        reuse: p.reuse ?? null,
        abilities: p.abilities.map((a) => ({
          id: a.id,
          equivalence: a.equivalence,
          dependencies: a.dependencies ?? null,
        })),
      })),
    projectUpdates: rounds.flatMap((r) =>
      Object.entries(r.memory).flatMap(([actor, m]) =>
        (m.projects ?? []).map((p) => ({ tick: r.tick, actor, project: p })),
      ),
    ),
    finalPersonalRecords: world.actors.map((a) => ({
      actor: a.id,
      projects: a.memory.projects ?? {},
      knowledge: a.memory.knowledge ?? {},
      relationships: a.relationships,
    })),
    confirmedInformation: events.filter(
      (e) => e.type === 'information-confirmed',
    ),
    trials: events.filter(
      (e) => e.type === 'trial-result' || e.type === 'trial-material-consumed',
    ),
    practice: events.filter((e) => e.type === 'practice-confirmed'),
    exchanges: events.filter(
      (e) => e.type === 'finding-offered' || e.type === 'finding-accepted',
    ),
    processes: events.filter((e) =>
      ['process-progress', 'process-completed', 'process-stopped'].includes(
        e.type,
      ),
    ),
    ecology: events.filter((e) =>
      [
        'seed-dispersed',
        'plant-established',
        'animal-fed',
        'animal-born',
        'animal-injured',
        'local-hazard',
      ].includes(e.type),
    ),
    outstandingProcesses: world.processes,
    materialProvenance: world.stacks
      .filter((s) => s.processing)
      .map((s) => ({
        id: s.id,
        resource: s.resource,
        quantity: s.quantity,
        owner: s.owner,
        origin: s.origin,
        processing: s.processing,
      })),
    context: state.attempts.map((a) => ({
      id: a.id,
      role: a.role,
      tick: a.tick,
      reason: a.reason,
      status: a.status,
      inputUtf8Bytes: a.contextBytes ?? null,
      inputCodeUnits: a.contextCodeUnits ?? null,
      inputTokens: a.usage?.inputTokens ?? null,
      outputTokens: a.usage?.outputTokens ?? null,
      elapsedMs: a.elapsedMs,
    })),
    interpretation:
      'Project completion and benefit fields are actor claims. Corroborate them with actual events, material provenance and subsequent execution. Fixtures and historical implementation reuse are not independent emergent discoveries. Context byte measurements cover input content; reported provider tokens include actual model accounting. Internal development usage is unknown.',
  };
}

scripts/open-evidence.ts:
import type { V7World } from '@self-evolving-world/world-core';
import type { V7RoundRecord } from '../apps/simulator/src/continuous-run.js';

/** Descriptive evidence, not inferred purpose, causality or automatic success scores. */
export function openEvidence(frames: V7World[], rounds: V7RoundRecord[]) {
  const events = rounds.flatMap((r) => r.events);
  const continuing = new Map<
    string,
    {
      actor: string;
      ability: string;
      startedAt: number;
      firstObserved: number;
      lastObserved: number;
      observedRounds: number;
      maximumElapsed: number;
      unchangedRemainingTransitions: number;
      remaining: number | null;
    }
  >();
  for (const r of rounds)
    for (const [actor, task] of Object.entries(r.tasks)) {
      const op = task.operation;
      if (!op) continue;
      const key = `${actor}:${String(op.startedAt)}:${op.action.interface}`;
      const previous = continuing.get(key);
      continuing.set(key, {
        actor,
        ability: op.action.interface,
        startedAt: op.startedAt,
        firstObserved: previous?.firstObserved ?? r.tick,
        lastObserved: r.tick,
        observedRounds: (previous?.observedRounds ?? 0) + 1,
        maximumElapsed: Math.max(previous?.maximumElapsed ?? 0, op.elapsed),
        unchangedRemainingTransitions:
          (previous?.unchangedRemainingTransitions ?? 0) +
          (previous &&
          previous.lastObserved === r.tick - 1 &&
          op.remaining !== null &&
          op.remaining === previous.remaining
            ? 1
            : 0),
        remaining: op.remaining,
      });
    }
  const objects = new Map(
    frames.flatMap((f) =>
      f.objects
        .filter((o) => o.createdBy !== null)
        .map((o) => [o.id, o] as const),
    ),
  );
  const updates = new Map<string, { tick: number; status: string }>();
  const transitions: {
    tick: number;
    actor: string;
    project: string;
    previous: string;
    status: string;
  }[] = [];
  for (const r of rounds)
    for (const [actor, memory] of Object.entries(r.memory))
      for (const p of memory.projects ?? []) {
        const key = `${actor}:${p.id}`,
          previous = updates.get(key);
        if (previous && previous.status !== p.status)
          transitions.push({
            tick: r.tick,
            actor,
            project: p.id,
            previous: previous.status,
            status: p.status,
          });
        updates.set(key, { tick: r.tick, status: p.status });
      }
  return {
    interpretation:
      'Continuing work is not completed use. Unchanged remaining work is a stall candidate, not proof of a bug: passive waiting can be legitimate. Cross-actor object interactions are successful targeted events, not automatically benefits. Project status is an actor claim. Exposure readings are distinct from completed beneficial rest.',
    continuingOperations: [...continuing.values()],
    projectStatusTransitions: transitions,
    physicalMeasurements: events.filter((e) =>
      [
        'assay-reading',
        'food-examination-completed',
        'shelter-inspected',
        'shelter-material-tested',
        'woven-support-test',
        'hardness-comparison-completed',
        'contact-calibration-completed',
        'metrology-measured',
        'metrology-load-tested',
        'preservation-reading',
        'short-refuge-trial',
        'short-refuge-exposure',
      ].includes(e.type),
    ),
    repeatedObstructions: events.filter(
      (e) =>
        e.type.endsWith('-progress') &&
        /missing|unavailable|insufficient|waiting/i.test(e.description),
    ),
    preservationTrials: events.filter((e) =>
      [
        'preservation-inspected',
        'preservation-reading',
        'preservation-completed',
        'preservation-stopped',
      ].includes(e.type),
    ),
    foodWaterTransfers: events.filter(
      (e) => e.type === 'preservation-progress' && e.data.audit !== undefined,
    ),
    shortRefugeTrials: events.filter((e) =>
      [
        'short-refuge-assessed',
        'short-refuge-trial',
        'short-refuge-completed',
        'short-refuge-exposure',
        'short-refuge-stopped',
      ].includes(e.type),
    ),
    waterOperations: events.filter((e) =>
      [
        'water-access-inspected',
        'water-cup-completed',
        'water-withdrawn',
        'material-contact-wetted',
        'water-cup-failed',
        'water-operation-stopped',
      ].includes(e.type),
    ),
    waterDeposits: events.filter((e) => e.type === 'water-spilled'),
    crossActorObjectInteractions: events.flatMap((e) => {
      const object = e.target ? objects.get(e.target) : undefined;
      return object && e.success && e.actor && e.actor !== object.createdBy
        ? [
            {
              tick: e.tick,
              actor: e.actor,
              creator: object.createdBy,
              object: object.id,
              type: e.type,
              interface: e.interface,
              data: e.data,
            },
          ]
        : [];
    }),
    completedBeneficialRest: events.filter(
      (e) => e.type === 'shelter-rest-experience',
    ),
    exposureReadings: events.filter(
      (e) => e.type === 'shelter-exposure-measured',
    ),
    actualPracticeMilestones: events.filter(
      (e) => e.type === 'practice-confirmed',
    ),
    finalGeneratedObjects: [...objects.values()].map((o) => ({
      id: o.id,
      kind: o.kind,
      creator: o.createdBy,
      createdAt: o.createdAt,
      revision: o.revision,
      presentAtBoundary: frames
        .at(-1)
        ?.objects.some((current) => current.id === o.id),
      state: o.data,
    })),
  };
}

scripts/open-preflight.ts:
import {
  continuousRegistry,
  v7Step,
  v7Observe,
  v7Reach,
  v7Distance,
  forestRoute,
  v7Work,
  v7Approach,
  v7Clone,
} from '@self-evolving-world/world-core';
import type { V7Action } from '@self-evolving-world/world-core';
import { initialOpenWorld } from '../apps/simulator/src/open-scenario.js';

/** Isolated feasibility oracle. This file and its policy are never sent to the ordinary model. */
export function openPreflight(
  rounds = 1600,
  genesis = initialOpenWorld(),
  onStage?: (tick: number) => void,
) {
  let world = genesis;
  const registry = continuousRegistry(world),
    initial = world;
  const actions: Record<string, number> = {},
    failures: Record<string, number> = {},
    minima: Record<string, { health: number; satiety: number }> = {},
    firstFood: Record<string, number> = {};
  const food = (id: unknown) =>
    world.resources.find(
      (r) => r.id === id && r.nutrition > 0 && r.toxicity === 0,
    );
  const blocked = new Map<string, Set<string>>();
  let optionalActivityRounds = 0;
  for (let tick = 0; tick < rounds; tick++) {
    // This omniscient feasibility oracle is deliberately separate from private formal observations.
    world = v7Clone(world);
    for (const a of world.config.collective ? [] : world.actors) {
      a.memory.objects = world.objects.map((object) => ({
        object: v7Clone(object),
        seenAt: world.tick,
      }));
      a.memory.cells = world.terrain.flatMap((row, y) =>
        Array.from(
          { length: row.length },
          (_, x) => `${String(x)},${String(y)}`,
        ),
      );
    }
    const intents: Record<string, V7Action> = {};
    const reservedSources = new Set<string>();
    const movingGroups = new Set<string>();
    for (const actor of world.config.collective
      ? [...world.actors].sort(
          (a, b) =>
            a.vitals.satiety - b.vitals.satiety || a.id.localeCompare(b.id),
        )
      : world.actors) {
      const o = v7Observe(world, actor.id);
      const owned = world.stacks.find(
        (s) => s.owner === actor.id && !s.reservedFor && food(s.resource),
      );
      const available = [
        ...o.objects,
        ...actor.memory.objects
          .filter((m) => !o.objects.some((x) => x.id === m.object.id))
          .map((m) => m.object),
      ]
        .filter(
          (x) =>
            food(x.data.resource) &&
            Number(x.data.stock) > 0 &&
            !blocked.get(actor.id)?.has(x.id) &&
            !reservedSources.has(x.id) &&
            (world.config.collective ||
              initial.actors
                .slice()
                .sort(
                  (a, b) =>
                    v7Distance(a.position, x.spatial) -
                    v7Distance(b.position, x.spatial),
                )[0]?.id === actor.id),
        )
        .sort(
          (a, b) =>
            v7Distance(actor.position, a.spatial) -
            v7Distance(actor.position, b.spatial),
        );
      const source = available[0];
      const visibleSource =
        source ??
        world.objects
          .filter(
            (x) =>
              food(x.data.resource) &&
              Number(x.data.stock) > 0 &&
              !blocked.get(actor.id)?.has(x.id) &&
              !reservedSources.has(x.id) &&
              (world.config.collective ||
                initial.actors
                  .slice()
                  .sort(
                    (a, b) =>
                      v7Distance(a.position, x.spatial) -
                      v7Distance(b.position, x.spatial),
                  )[0]?.id === actor.id),
          )
          .sort(
            (a, b) =>
              v7Distance(actor.position, a.spatial) -
              v7Distance(actor.position, b.spatial),
          )[0];
      if (actor.learning) intents[actor.id] = { interface: 'wait', args: {} };
      else if (actor.vitals.satiety < 78 && owned)
        intents[actor.id] = {
          interface: 'eat',
          args: { target: owned.id, quantity: 1 },
        };
      else if (actor.vitals.energy < 8)
        intents[actor.id] = { interface: 'rest', args: {} };
      else if (actor.vitals.satiety < 78 && visibleSource) {
        if (world.config.collective) reservedSources.add(visibleSource.id);
        if (v7Reach(actor, visibleSource.spatial))
          intents[actor.id] = {
            interface: 'gather',
            args: { target: visibleSource.id, quantity: 1 },
          };
        else {
          const group = actor.collective?.group;
          if (group && movingGroups.has(group)) {
            intents[actor.id] = { interface: 'wait', args: {} };
            continue;
          }
          // The isolated oracle may search real interaction points; it still pays continuous movement and collision costs.
          const center = visibleSource.spatial;
          const points = [
            v7Approach(actor, center),
            ...Array.from({ length: 16 }, (_, i) => ({
              x: center.x + Math.cos((i * Math.PI) / 8) * 0.8,
              y: center.y + Math.sin((i * Math.PI) / 8) * 0.8,
            })),
          ];
          const point = points.find(
            (p) =>
              forestRoute(
                world,
                actor,
                p,
                v7Work(world.config.computation.workPerRound),
              ).path.length > 0,
          );
          if (point) {
            if (group) movingGroups.add(group);
            intents[actor.id] = {
              interface: 'navigate',
              args: { target: '', x: point.x, y: point.y },
            };
          } else {
            const set = blocked.get(actor.id) ?? new Set<string>();
            set.add(visibleSource.id);
            blocked.set(actor.id, set);
            intents[actor.id] = { interface: 'wait', args: {} };
          }
        }
      } else {
        if (actor.vitals.satiety >= 78 && actor.vitals.energy >= 35)
          optionalActivityRounds++;
        intents[actor.id] = {
          interface: actor.vitals.energy < 35 ? 'rest' : 'wait',
          args: {},
        };
      }
    }
    const result = v7Step(world, intents, registry);
    if (result.paused) throw new Error(result.paused);
    world = result.world;
    for (const actor of world.actors) {
      const action = intents[actor.id],
        outcome = result.outcomes[actor.id];
      actions[action?.interface ?? 'none'] =
        (actions[action?.interface ?? 'none'] ?? 0) + 1;
      if (outcome && !outcome.success) {
        failures[outcome.reason] = (failures[outcome.reason] ?? 0) + 1;
        if (typeof action?.args.target === 'string') {
          const set = blocked.get(actor.id) ?? new Set<string>();
          set.add(action.args.target);
          blocked.set(actor.id, set);
        }
      }
      if (
        action?.interface === 'gather' &&
        outcome?.success &&
        firstFood[actor.id] === undefined
      )
        firstFood[actor.id] = world.tick;
      const prior = minima[actor.id] ?? { health: 100, satiety: 100 };
      minima[actor.id] = {
        health: Math.min(prior.health, actor.vitals.health),
        satiety: Math.min(prior.satiety, actor.vitals.satiety),
      };
      if ((actor.life?.deaths ?? 0) > 0)
        throw new Error(
          `Isolated baseline lost a life: ${actor.id} at ${String(world.tick)}; ${JSON.stringify({ minima, actions, failures })}`,
        );
    }
    if (tick % 80 === 79) blocked.clear();
    if (world.tick % 200 === 0) onStage?.(world.tick);
  }
  const spare = world.config.collective
    ? optionalActivityRounds
    : (actions.wait ?? 0);
  if (spare < rounds * initial.actors.length * 0.15)
    throw new Error('Baseline leaves less than 15% optional activity time.');
  return {
    version: 1,
    controller: 'isolated-fresh-development-feasibility',
    modelCalls: 0,
    rounds,
    seed: initial.config.seed,
    configuration: initial.config,
    firstFoodRound: firstFood,
    initialSafeNutrition: initial.objects.reduce(
      (n, x) =>
        n + Number(x.data.stock ?? 0) * (food(x.data.resource)?.nutrition ?? 0),
      0,
    ),
    nearestFoodDistances: initial.actors.map((a) => ({
      actor: a.id,
      distance: Math.min(
        ...initial.objects
          .filter((x) => food(x.data.resource))
          .map((x) => v7Distance(a.position, x.spatial)),
      ),
    })),
    minima,
    actions,
    failures,
    optionalRounds: spare,
    optionalShare: spare / (rounds * initial.actors.length),
    final: world.actors.map((a) => ({
      id: a.id,
      vitals: a.vitals,
      lives: a.life,
      mental: a.experience?.mental,
    })),
    limitation:
      'Authored offline feasibility only; no autonomous discovery or causal guarantee. Oracle uses actual safe definitions, which are excluded from ordinary inputs.',
  };
}

scripts/open-registration.test.ts:
import { readFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import { v7Clone } from '@self-evolving-world/world-core';
import {
  bindRegistrationPrecision,
  reconstructContinuousSegment,
} from './continuous-store.js';
import type { V7ReplaySegment } from './continuous-store.js';
const original = JSON.parse(
  readFileSync('experiment/ex10/replay/execution-000100-000123.json', 'utf8'),
) as V7ReplaySegment;
const frames = reconstructContinuousSegment(original);
const index = original.rounds.findIndex((r) =>
  r.registrations.includes('material-geometry@1'),
);
const before = frames[index],
  record = original.rounds[index];
if (!before || !record) throw new Error('Missing retained actual migration');
it('binds supplementary browser precision to the actual original migration without changing any original round field', () => {
  const bound = bindRegistrationPrecision(before, record);
  expect(bound.registrationPrecisionHash).toMatch(/^[a-f0-9]{64}$/);
  const { registrationPrecisionHash: proof, ...retained } = bound;
  expect(proof).toBeTruthy();
  expect(retained).toEqual(record);
  expect(() =>
    bindRegistrationPrecision(before, { ...record, before: 'invalid' }),
  ).toThrow('different original prefix');
  const segment = v7Clone(original);
  segment.rounds[index] = bound;
  expect(reconstructContinuousSegment(segment)).toEqual(frames);
});
it('rejects corrupt precision evidence, raw prefix tampering and precision proofs attached to unrelated rounds', () => {
  for (const field of ['before', 'registrationPrecisionHash'] as const) {
    const segment = v7Clone(original),
      bound = bindRegistrationPrecision(before, record);
    bound[field] = 'invalid';
    segment.rounds[index] = bound;
    expect(() => reconstructContinuousSegment(segment)).toThrow();
  }
  const segment = v7Clone(original),
    first = segment.rounds[0];
  if (!first) throw new Error('Missing record');
  first.registrationPrecisionHash = 'invalid';
  expect(() => reconstructContinuousSegment(segment)).toThrow(
    'Invalid supplementary',
  );
});

